window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7aeae00a1f8e3ba4"]={"versions": [{"id": "FIG-7aeae00a1f8e3ba4", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Kommunikationsattributen für Kalibrierparameter auf Empfängerseite (Require-Seite) innerhalb der AUTOSAR-Software-Komponenten-Architektur (AUTOSAR Classic Platform, Meta-Modell-Paket <code>AUTOSAR_SoftwareComponentTemplate</code>). Der Kontext umfasst die Zuordnung von Initialisierungswerten zu Schnittstellenbeschreibungen an R-Ports.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Metaklassen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>PortPrototype</code> (kursiv/abstrakt): Oberklasse für Ports.</li>\n<li><code>RPortPrototype</code> (im Paket <code>Components</code>, mit Stereotyp <code>«atpPrototype»</code>): Spezialisierung bzw. Prototyp eines Require-Ports, aggregiert per Komposition (<code>+requiredComSpec 0..*</code>) Instanzen von <code>RPortComSpec</code>.</li>\n<li><code>RPortComSpec</code> (kursiv/abstrakt): Abstrakte Basisklasse für empfängerseitige Kommunikationsspezifikationen.</li>\n<li><code>InitValueAssignment</code> (im Namensraum <code>ComponentLocalCalprm</code>): Abstrakte Schnittstelle/Klasse für die Zuweisung von Initialwerten; referenziert über eine gerichtete Assoziation <code>+initValue</code> mit Multiplizität <code>1</code> das Ziel <code>ValueSpecification</code> (aus dem Paket <code>Constants</code>, bezogen auf <code>DataPrototype</code>).</li>\n<li><code>ParameterRequireComSpec</code>: Konkrete Spezialisierung, die mehrfach erbt: einerseits per Generalisierung von <code>RPortComSpec</code>, andererseits per Generalisierung von <code>ComponentLocalCalprm::InitValueAssignment</code>. Dadurch besitzt <code>ParameterRequireComSpec</code> genau einen Initialwert (<code>initValue</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm des AUTOSAR-Metamodells ohne dynamische Ablaufsequenz. Zur Konfigurations- und Generierungszeit definiert <code>ParameterRequireComSpec</code> die Kommunikationsparameter eines Kalibrierungs-R-Ports, wobei der R-Port über <code>+initValue 1</code> einen deterministischen Vorgabewert (<code>ValueSpecification</code>) erhält, der beim Systemstart bzw. vor dem Empfang valider Parameterwerte von der RTE herangezogen wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Metamodell-Definition für Kalibrierparameter an <code>RPortPrototype</code>. Entwickler und Generatoren-Autoren müssen sicherstellen, dass jede <code>ParameterRequireComSpec</code> genau eine <code>ValueSpecification</code> als <code>initValue</code> definiert (Multiplizität 1) und an einem <code>RPortPrototype</code> verankert ist. Die Mehrfachvererbung von <code>RPortComSpec</code> und <code>InitValueAssignment</code> ist bei M2-konformen Werkzeugen und XML-Serialisierungen zu berücksichtigen.</p>"}, {"id": "FIG-6bc0934fc6ed5822", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Kommunikationsattributen für Kalibrierparameter auf Sender-/Bereitstellerseite (Provide-Seite) innerhalb der AUTOSAR-Software-Komponenten-Architektur (AUTOSAR Classic Platform, Meta-Modell-Paket <code>AUTOSAR_SoftwareComponentTemplate</code>). Der Kontext umfasst die Konfiguration von Initialwerten an P-Ports für Parameter.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Metaklassen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>PortPrototype</code> (kursiv/abstrakt): Oberklasse für Port-Prototypen.</li>\n<li><code>PPortPrototype</code> (mit Stereotyp <code>«atpPrototype»</code>): Prototyp eines Provide-Ports, aggregiert per Komposition (<code>+providedComSpec 0..*</code>) Instanzen von <code>PPortComSpec</code>.</li>\n<li><code>PPortComSpec</code> (kursiv/abstrakt): Abstrakte Basisklasse für senderseitige Kommunikationsspezifikationen.</li>\n<li><code>InitValueAssignment</code>: Abstrakte Klasse zur Initialwertzuweisung; assoziiert über die gerichtete Beziehung <code>+initValue</code> mit Kardinalität <code>1</code> eine <code>ValueSpecification</code> (bezogen auf <code>DataPrototype</code>).</li>\n<li><code>ParameterProvideComSpec</code>: Konkrete Spezialisierung, die sowohl von <code>PPortComSpec</code> als auch von <code>InitValueAssignment</code> generalisiert/erbt. Damit verfügt die Kommunikationsspezifikation eines Parameter-P-Ports obligatorisch über genau einen Initialwert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm ohne Laufzeitsequenz. Im Entwicklungs- und Generierungsprozess stellt <code>ParameterProvideComSpec</code> sicher, dass für einen bereitgestellten Kalibrierparameter an einem <code>PPortPrototype</code> zwingend ein definierter Initialwert (<code>ValueSpecification</code>) existiert, welcher von der RTE bei der Initialisierung des Parameterspeichers bereitgestellt wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Spezifikation für Parameter-P-Ports. Für jede Instanz von <code>ParameterProvideComSpec</code> muss im AUTOSAR-XML-Modell genau ein <code>initValue</code> hinterlegt sein (Multiplizität 1). Werkzeuge zur RTE- und Komponenten-Generierung müssen die Mehrfachvererbung aus <code>PPortComSpec</code> und <code>InitValueAssignment</code> auflösen und die konsistente Bereitstellung der Werte zur Initialisierungsphase garantieren.</p>"}, {"id": "FIG-40ffb26dc382f8d2", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Kommunikationsattributen für Kalibrierparameter auf Empfängerseite (Require-Seite) innerhalb der AUTOSAR-Software-Komponenten-Architektur (AUTOSAR Classic Platform, Meta-Modell-Paket <code>AUTOSAR_SoftwareComponentTemplate</code>). Der Kontext umfasst die Zuordnung von Initialisierungswerten zu Schnittstellenbeschreibungen an R-Ports.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Metaklassen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>PortPrototype</code> (kursiv/abstrakt): Oberklasse für Ports.</li>\n<li><code>RPortPrototype</code> (im Paket <code>Components</code>, mit Stereotyp <code>«atpPrototype»</code>): Spezialisierung bzw. Prototyp eines Require-Ports, aggregiert per Komposition (<code>+requiredComSpec 0..*</code>) Instanzen von <code>RPortComSpec</code>.</li>\n<li><code>RPortComSpec</code> (kursiv/abstrakt): Abstrakte Basisklasse für empfängerseitige Kommunikationsspezifikationen.</li>\n<li><code>InitValueAssignment</code> (im Namensraum <code>ComponentLocalCalprm</code>): Abstrakte Schnittstelle/Klasse für die Zuweisung von Initialwerten; referenziert über eine gerichtete Assoziation <code>+initValue</code> mit Multiplizität <code>1</code> das Ziel <code>ValueSpecification</code> (aus dem Paket <code>Constants</code>, bezogen auf <code>DataPrototype</code>).</li>\n<li><code>ParameterRequireComSpec</code>: Konkrete Spezialisierung, die mehrfach erbt: einerseits per Generalisierung von <code>RPortComSpec</code>, andererseits per Generalisierung von <code>ComponentLocalCalprm::InitValueAssignment</code>. Dadurch besitzt <code>ParameterRequireComSpec</code> genau einen Initialwert (<code>initValue</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm des AUTOSAR-Metamodells ohne dynamische Ablaufsequenz. Zur Konfigurations- und Generierungszeit definiert <code>ParameterRequireComSpec</code> die Kommunikationsparameter eines Kalibrierungs-R-Ports, wobei der R-Port über <code>+initValue 1</code> einen deterministischen Vorgabewert (<code>ValueSpecification</code>) erhält, der beim Systemstart bzw. vor dem Empfang valider Parameterwerte von der RTE herangezogen wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Metamodell-Definition für Kalibrierparameter an <code>RPortPrototype</code>. Entwickler und Generatoren-Autoren müssen sicherstellen, dass jede <code>ParameterRequireComSpec</code> genau eine <code>ValueSpecification</code> als <code>initValue</code> definiert (Multiplizität 1) und an einem <code>RPortPrototype</code> verankert ist. Die Mehrfachvererbung von <code>RPortComSpec</code> und <code>InitValueAssignment</code> ist bei M2-konformen Werkzeugen und XML-Serialisierungen zu berücksichtigen.</p>"}, {"id": "FIG-24e601dddcfd0693", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Kommunikationsattributen für Kalibrierparameter auf Empfängerseite (Require-Seite) innerhalb der AUTOSAR-Software-Komponenten-Architektur (AUTOSAR Classic Platform, Meta-Modell-Paket <code>AUTOSAR_SoftwareComponentTemplate</code>). Der Kontext umfasst die Zuordnung von Initialisierungswerten zu Schnittstellenbeschreibungen an R-Ports.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Metaklassen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>PortPrototype</code> (kursiv/abstrakt): Oberklasse für Ports.</li>\n<li><code>RPortPrototype</code> (im Paket <code>Components</code>, mit Stereotyp <code>«atpPrototype»</code>): Spezialisierung bzw. Prototyp eines Require-Ports, aggregiert per Komposition (<code>+requiredComSpec 0..*</code>) Instanzen von <code>RPortComSpec</code>.</li>\n<li><code>RPortComSpec</code> (kursiv/abstrakt): Abstrakte Basisklasse für empfängerseitige Kommunikationsspezifikationen.</li>\n<li><code>InitValueAssignment</code> (im Namensraum <code>ComponentLocalCalprm</code>): Abstrakte Schnittstelle/Klasse für die Zuweisung von Initialwerten; referenziert über eine gerichtete Assoziation <code>+initValue</code> mit Multiplizität <code>1</code> das Ziel <code>ValueSpecification</code> (aus dem Paket <code>Constants</code>, bezogen auf <code>DataPrototype</code>).</li>\n<li><code>ParameterRequireComSpec</code>: Konkrete Spezialisierung, die mehrfach erbt: einerseits per Generalisierung von <code>RPortComSpec</code>, andererseits per Generalisierung von <code>ComponentLocalCalprm::InitValueAssignment</code>. Dadurch besitzt <code>ParameterRequireComSpec</code> genau einen Initialwert (<code>initValue</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm des AUTOSAR-Metamodells ohne dynamische Ablaufsequenz. Zur Konfigurations- und Generierungszeit definiert <code>ParameterRequireComSpec</code> die Kommunikationsparameter eines Kalibrierungs-R-Ports, wobei der R-Port über <code>+initValue 1</code> einen deterministischen Vorgabewert (<code>ValueSpecification</code>) erhält, der beim Systemstart bzw. vor dem Empfang valider Parameterwerte von der RTE herangezogen wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Metamodell-Definition für Kalibrierparameter an <code>RPortPrototype</code>. Entwickler und Generatoren-Autoren müssen sicherstellen, dass jede <code>ParameterRequireComSpec</code> genau eine <code>ValueSpecification</code> als <code>initValue</code> definiert (Multiplizität 1) und an einem <code>RPortPrototype</code> verankert ist. Die Mehrfachvererbung von <code>RPortComSpec</code> und <code>InitValueAssignment</code> ist bei M2-konformen Werkzeugen und XML-Serialisierungen zu berücksichtigen.</p>"}, {"id": "FIG-0b5af0973f9a56f0", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Kommunikationsattributen für Kalibrierparameter auf Sender-/Bereitstellerseite (Provide-Seite) innerhalb der AUTOSAR-Software-Komponenten-Architektur (AUTOSAR Classic Platform, Meta-Modell-Paket <code>AUTOSAR_SoftwareComponentTemplate</code>). Der Kontext umfasst die Konfiguration von Initialwerten an P-Ports für Parameter.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Metaklassen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>PortPrototype</code> (kursiv/abstrakt): Oberklasse für Port-Prototypen.</li>\n<li><code>PPortPrototype</code> (mit Stereotyp <code>«atpPrototype»</code>): Prototyp eines Provide-Ports, aggregiert per Komposition (<code>+providedComSpec 0..*</code>) Instanzen von <code>PPortComSpec</code>.</li>\n<li><code>PPortComSpec</code> (kursiv/abstrakt): Abstrakte Basisklasse für senderseitige Kommunikationsspezifikationen.</li>\n<li><code>InitValueAssignment</code>: Abstrakte Klasse zur Initialwertzuweisung; assoziiert über die gerichtete Beziehung <code>+initValue</code> mit Kardinalität <code>1</code> eine <code>ValueSpecification</code> (bezogen auf <code>DataPrototype</code>).</li>\n<li><code>ParameterProvideComSpec</code>: Konkrete Spezialisierung, die sowohl von <code>PPortComSpec</code> als auch von <code>InitValueAssignment</code> generalisiert/erbt. Damit verfügt die Kommunikationsspezifikation eines Parameter-P-Ports obligatorisch über genau einen Initialwert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm ohne Laufzeitsequenz. Im Entwicklungs- und Generierungsprozess stellt <code>ParameterProvideComSpec</code> sicher, dass für einen bereitgestellten Kalibrierparameter an einem <code>PPortPrototype</code> zwingend ein definierter Initialwert (<code>ValueSpecification</code>) existiert, welcher von der RTE bei der Initialisierung des Parameterspeichers bereitgestellt wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Spezifikation für Parameter-P-Ports. Für jede Instanz von <code>ParameterProvideComSpec</code> muss im AUTOSAR-XML-Modell genau ein <code>initValue</code> hinterlegt sein (Multiplizität 1). Werkzeuge zur RTE- und Komponenten-Generierung müssen die Mehrfachvererbung aus <code>PPortComSpec</code> und <code>InitValueAssignment</code> auflösen und die konsistente Bereitstellung der Werte zur Initialisierungsphase garantieren.</p>"}], "trans": []};
